-- One shared table; Postgres enforces isolation instead of every query remembering it
ALTER TABLE chunks ENABLE ROW LEVEL SECURITY;
ALTER TABLE chunks FORCE ROW LEVEL SECURITY;   -- applies to the table owner too

CREATE POLICY tenant_isolation ON chunks
  USING (tenant_id = current_setting('app.tenant_id')::uuid)
  WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);

-- The app connects as a role that cannot bypass RLS (and is not a superuser)
CREATE ROLE app_rw LOGIN NOBYPASSRLS;
GRANT SELECT, INSERT, UPDATE, DELETE ON chunks TO app_rw;

-- Per request. $1 = tenant from the VERIFIED auth token,
-- never from the request body or an LLM tool argument
BEGIN;
SELECT set_config('app.tenant_id', $1, true);  -- true = local to this transaction
SELECT id, content
FROM chunks
ORDER BY embedding <=> $2                       -- pgvector cosine distance
LIMIT 20;                                       -- RLS adds the tenant filter for you
COMMIT;
-- No tenant set -> current_setting() raises or ''::uuid fails: the query fails closed
